def fill_uniform_rects(grid, min_h=5, min_w=5):
    h,w=len(grid),len(grid[0])
    out=[row[:] for row in grid]
    for r in range(h-min_h+1):
        for c in range(w-min_w+1):
            x=grid[r][c]
            if all(grid[i][j]==x for i in range(r,r+min_h) for j in range(c,c+min_w)):
                for i in range(r,r+min_h):
                    for j in range(c,c+min_w): out[i][j]=4
    return out
